import{_ as e,o as s,c as n,ai as l}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Redis 面试连环追问（口述链）","description":"","frontmatter":{},"headers":[],"relativePath":"redis/interview-chain.md","filePath":"redis/interview-chain.md"}'),r={name:"redis/interview-chain.md"};function i(t,a,o,p,d,c){return s(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="redis-面试连环追问-口述链" tabindex="-1">Redis 面试连环追问（口述链） <a class="header-anchor" href="#redis-面试连环追问-口述链" aria-label="Permalink to “Redis 面试连环追问（口述链）”">​</a></h1><p>一条真实面试里很常见的追问路径。目标不是再学一遍知识点，而是：<strong>从上到下能连续讲 8～15 分钟，每一环都能接住下一问。</strong></p><p>详细专题仍看分区文章；本页是「串起来怎么说」。</p><p>练习方式：先看稿 → 只看小标题 → 脱稿。卡在哪一环，回对应专题补。</p><hr><h2 id="整条链-先看地图" tabindex="-1">整条链（先看地图） <a class="header-anchor" href="#整条链-先看地图" aria-label="Permalink to “整条链（先看地图）”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Redis</span></span>
<span class="line"><span> ↓ 为什么快</span></span>
<span class="line"><span> ↓ 单线程</span></span>
<span class="line"><span> ↓ Redis 6</span></span>
<span class="line"><span> ↓ 数据结构</span></span>
<span class="line"><span> ↓ ZSet 排行榜</span></span>
<span class="line"><span> ↓ 缓存</span></span>
<span class="line"><span> ↓ 缓存穿透</span></span>
<span class="line"><span> ↓ 缓存击穿</span></span>
<span class="line"><span> ↓ 分布式锁</span></span>
<span class="line"><span> ↓ SET NX</span></span>
<span class="line"><span> ↓ 为什么要 EX / PX</span></span>
<span class="line"><span> ↓ 为什么要唯一 value</span></span>
<span class="line"><span> ↓ Lua</span></span>
<span class="line"><span> ↓ Redisson</span></span>
<span class="line"><span> ↓ 看门狗</span></span>
<span class="line"><span> ↓ 缓存一致性</span></span>
<span class="line"><span> ↓ MySQL</span></span>
<span class="line"><span> ↓ MQ</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><hr><h2 id="_1-redis-是什么-开场" tabindex="-1">1. Redis 是什么？（开场） <a class="header-anchor" href="#_1-redis-是什么-开场" aria-label="Permalink to “1. Redis 是什么？（开场）”">​</a></h2><blockquote><p>Redis 是基于内存的高性能键值库。项目里我主要用它做缓存、分布式锁、计数、限流和临时状态，不是当业务主库替代 MySQL。</p></blockquote><p>展开一句即可，别一上来背全部命令。</p><p>专题：<a href="./01-basics.html">基础原理</a> · <a href="./">总览</a></p><hr><h2 id="_2-为什么快" tabindex="-1">2. 为什么快？ <a class="header-anchor" href="#_2-为什么快" aria-label="Permalink to “2. 为什么快？”">​</a></h2><p>口述四条就够：</p><ol><li><strong>内存读写</strong>，比磁盘快几个数量级</li><li><strong>高效数据结构</strong>（哈希、跳表等）</li><li><strong>I/O 多路复用</strong>，单线程也能扛很多连接</li><li><strong>命令简单</strong>，多数复杂度低</li></ol><p>加一句边界：</p><blockquote><p>快不等于不会慢。大 Key、热 Key、<code>KEYS *</code>、慢命令一样能把实例拖垮。</p></blockquote><hr><h2 id="_3-单线程-那不会成为瓶颈吗" tabindex="-1">3. 单线程？那不会成为瓶颈吗？ <a class="header-anchor" href="#_3-单线程-那不会成为瓶颈吗" aria-label="Permalink to “3. 单线程？那不会成为瓶颈吗？”">​</a></h2><blockquote><p>说的「单线程」主要指<strong>命令执行</strong>在一个主线程里串行跑，所以单命令原子、不用复杂锁。<br> 但进程里不只有这一个线程；而且一个慢命令会堵住后面所有请求。</p></blockquote><p>生产禁忌：<code>KEYS *</code>、胡乱 <code>HGETALL</code> 超大 Hash、同步 <code>DEL</code> 超大 Key（改用 <code>SCAN</code> / <code>UNLINK</code>）。</p><hr><h2 id="_4-redis-6-呢-不是多线程了吗" tabindex="-1">4. Redis 6 呢？不是多线程了吗？ <a class="header-anchor" href="#_4-redis-6-呢-不是多线程了吗" aria-label="Permalink to “4. Redis 6 呢？不是多线程了吗？”">​</a></h2><blockquote><p>Redis 6 可以把部分 <strong>网络读写</strong> 交给 I/O 线程并行，减轻读写 socket 的压力。<br><strong>命令执行仍然主要在主线程</strong>，业务上还是按「命令串行」来设计，不能假设多个写逻辑在服务端并行交错执行同一把锁。</p></blockquote><hr><h2 id="_5-常用数据结构-举个例子" tabindex="-1">5. 常用数据结构？举个例子 <a class="header-anchor" href="#_5-常用数据结构-举个例子" aria-label="Permalink to “5. 常用数据结构？举个例子”">​</a></h2><p>快速带过五件套 + 特殊类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>我怎么用</th></tr></thead><tbody><tr><td>String</td><td>缓存 JSON、计数、<code>SET NX</code> 锁</td></tr><tr><td>Hash</td><td>对象字段、可部分更新</td></tr><tr><td>List</td><td>简单队列、最新列表</td></tr><tr><td>Set</td><td>去重、共同好友</td></tr><tr><td>ZSet</td><td><strong>排行榜</strong>、延迟任务</td></tr><tr><td>Bitmap / HLL</td><td>签到、近似 UV</td></tr><tr><td>Stream</td><td>轻量消息流</td></tr></tbody></table><hr><h2 id="_6-zset-怎么做排行榜" tabindex="-1">6. ZSet 怎么做排行榜？ <a class="header-anchor" href="#_6-zset-怎么做排行榜" aria-label="Permalink to “6. ZSet 怎么做排行榜？”">​</a></h2><blockquote><p>Key 是榜单，member 是用户/内容，score 是热度或分数。<code>ZINCRBY</code> 更新分数，<code>ZREVRANGE</code> 取 TopN。</p></blockquote><p>可追问时补：</p><ul><li>日榜/周榜用不同 Key</li><li>榜太大要裁剪</li><li>并列分数靠 member 或次级排序策略</li><li>底层小数据压缩结构，大数据 <strong>跳表 + 字典</strong>（范围查询友好）</li></ul><p>专题：<a href="./data-types.html">数据类型</a> · <a href="./10-practice.html">实战·排行榜</a></p><hr><h2 id="_7-缓存一般怎么用" tabindex="-1">7. 缓存一般怎么用？ <a class="header-anchor" href="#_7-缓存一般怎么用" aria-label="Permalink to “7. 缓存一般怎么用？”">​</a></h2><blockquote><p>读多写少的热点数据放 Redis。典型路径：先查缓存，未命中查 MySQL，回写缓存并设过期（最好加随机，防雪崩）。</p></blockquote><p>架构演进可一句带过：单 Redis → 热点加本地缓存（Caffeine）→ 保护 DB。</p><p>专题：<a href="./cache-issues.html">缓存问题</a> · <a href="./cache-scenario.html">缓存架构</a></p><hr><h2 id="_8-缓存穿透是什么-怎么防" tabindex="-1">8. 缓存穿透是什么？怎么防？ <a class="header-anchor" href="#_8-缓存穿透是什么-怎么防" aria-label="Permalink to “8. 缓存穿透是什么？怎么防？”">​</a></h2><blockquote><p><strong>查根本不存在的数据</strong>：缓存没有，DB 也没有，每次都打穿到 DB（常被恶意扫库）。</p></blockquote><p>防：</p><ul><li>缓存空值（短 TTL）</li><li>布隆过滤器（说不存在就一定不存在；说存在可能误判）</li></ul><hr><h2 id="_9-缓存击穿呢-和穿透有什么区别" tabindex="-1">9. 缓存击穿呢？和穿透有什么区别？ <a class="header-anchor" href="#_9-缓存击穿呢-和穿透有什么区别" aria-label="Permalink to “9. 缓存击穿呢？和穿透有什么区别？”">​</a></h2><blockquote><p><strong>热点 Key 刚好过期</strong>，瞬时大量请求打到 DB。<br> 穿透是「数据本来就不存在」；击穿是「热点存在但缓存空窗」。</p></blockquote><p>防：</p><ul><li>互斥锁：只有一个线程回源，其它等待重试</li><li>逻辑过期：先返回旧值，后台异步刷新</li></ul><p>（若再问雪崩：大量 Key 同时过期或 Redis 挂了 → 过期随机 + 限流降级 + 高可用。）</p><hr><h2 id="_10-分布式锁为什么用-redis" tabindex="-1">10. 分布式锁为什么用 Redis？ <a class="header-anchor" href="#_10-分布式锁为什么用-redis" aria-label="Permalink to “10. 分布式锁为什么用 Redis？”">​</a></h2><blockquote><p>多实例下 JVM 锁管不住。Redis 单线程执行命令 + <code>SET key value NX PX</code>，适合做跨进程互斥（库存预扣、防重复提交、定时任务抢主等）。</p></blockquote><p>边界：金融级强一致可考虑 ZK；多数业务 Redisson + DB 乐观锁兜底即可。</p><p>专题：<a href="./distributed-lock.html">分布式锁</a></p><hr><h2 id="_11-set-nx-是什么意思" tabindex="-1">11. SET NX 是什么意思？ <a class="header-anchor" href="#_11-set-nx-是什么意思" aria-label="Permalink to “11. SET NX 是什么意思？”">​</a></h2><blockquote><p><code>NX</code> = Not eXists：Key 不存在才设置成功 → 抢到锁；已存在则失败 → 没抢到。</p></blockquote><p>完整推荐写法：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SET lock_key unique_value NX PX 30000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不要拆成先 <code>SETNX</code> 再 <code>EXPIRE</code>。</p><hr><h2 id="_12-为什么一定要-ex-px-过期" tabindex="-1">12. 为什么一定要 EX / PX（过期）？ <a class="header-anchor" href="#_12-为什么一定要-ex-px-过期" aria-label="Permalink to “12. 为什么一定要 EX / PX（过期）？”">​</a></h2><blockquote><p>防止持锁进程宕机后<strong>死锁</strong>。<br> 若 <code>SETNX</code> 成功后、还没 <code>EXPIRE</code> 就挂了，锁永远不释放。所以 <strong>NX 和 PX 必须同一条命令原子完成</strong>。</p></blockquote><hr><h2 id="_13-为什么-value-必须唯一" tabindex="-1">13. 为什么 value 必须唯一？ <a class="header-anchor" href="#_13-为什么-value-必须唯一" aria-label="Permalink to “13. 为什么 value 必须唯一？”">​</a></h2><blockquote><p>防止<strong>误删别人的锁</strong>。<br> 场景：A 超时锁过期 → B 拿到锁 → A 业务结束执行 <code>DEL</code>，会把 B 的锁删掉。<br> 做法：value = UUID（+ 线程标识）；释放前校验「是不是我的」，是才删。</p></blockquote><hr><h2 id="_14-那为什么还要-lua" tabindex="-1">14. 那为什么还要 Lua？ <a class="header-anchor" href="#_14-那为什么还要-lua" aria-label="Permalink to “14. 那为什么还要 Lua？”">​</a></h2><blockquote><p>「先 GET 判断再 DEL」在客户端是两步，中间仍可能被打断，极端下仍会误删。<br> 用 <strong>Lua 把校验 + 删除做成一次原子脚本</strong> 交给 Redis 执行。Redisson 的 <code>unlock</code> 就是这么干的。</p></blockquote><p>Lua 也常用于：库存判断+扣减、限流窗口计数。专题：<a href="./07-concurrency.html">并发</a></p><hr><h2 id="_15-为什么还要-redisson-自己-set-不够吗" tabindex="-1">15. 为什么还要 Redisson？自己 SET 不够吗？ <a class="header-anchor" href="#_15-为什么还要-redisson-自己-set-不够吗" aria-label="Permalink to “15. 为什么还要 Redisson？自己 SET 不够吗？”">​</a></h2><blockquote><p>手写锁能讲清原理，生产更稳的是 Redisson：可重入、解锁封装、<strong>看门狗续期</strong>、少踩续期和误删的坑。</p></blockquote><hr><h2 id="_16-看门狗是什么" tabindex="-1">16. 看门狗是什么？ <a class="header-anchor" href="#_16-看门狗是什么" aria-label="Permalink to “16. 看门狗是什么？”">​</a></h2><blockquote><p>业务可能超过初始过期时间。看门狗在持锁期间周期性续期，避免锁提前释放导致并发不安全。<br> 进程挂了，看门狗也停，锁最终过期，避免永久死锁。<br><code>unlock</code> 放 <code>finally</code>；正常释放后不再续期。</p></blockquote><hr><h2 id="_17-缓存和-mysql-怎么保证一致" tabindex="-1">17. 缓存和 MySQL 怎么保证一致？ <a class="header-anchor" href="#_17-缓存和-mysql-怎么保证一致" aria-label="Permalink to “17. 缓存和 MySQL 怎么保证一致？”">​</a></h2><blockquote><p>常用 <strong>Cache Aside：先更新 MySQL，再删除缓存</strong>（让下次读取回源）。<br> 一般不采用「先更新缓存再写库」或「写库后更新缓存」当默认方案——并发下更容易脏数据，且写多读少时浪费。</p></blockquote><p>并发下仍可能有极短不一致；普通业务可接受。要求更高：</p><ul><li>延迟双删（慎用，要懂窗口）</li><li><strong>Canal 听 MySQL Binlog → 发 MQ → 消费者删缓存</strong>，靠重试做最终一致</li></ul><p>专题：<a href="./cache-scenario.html">缓存架构实战</a></p><hr><h2 id="_18-这里-mq-扮演什么角色-链的收口" tabindex="-1">18. 这里 MQ 扮演什么角色？（链的收口） <a class="header-anchor" href="#_18-这里-mq-扮演什么角色-链的收口" aria-label="Permalink to “18. 这里 MQ 扮演什么角色？（链的收口）”">​</a></h2><p>分清两件事，面试官常混着问：</p><p><strong>A. 用 Redis 当 MQ 行不行？</strong></p><ul><li>Pub/Sub：<strong>不能</strong>当可靠队列（不在线即丢、不持久）。</li><li>Stream：轻量可以，消费组/ACK 有了；订单等核心链路仍优先专业 MQ。</li></ul><p><strong>B. 缓存一致性链路里的 MQ：</strong></p><ul><li>不是用 Redis 替代 MQ，而是 <strong>Binlog → MQ → 删 Redis</strong>，保证删缓存可重试、最终一致。</li></ul><p>专题：<a href="./transaction-pubsub.html">消息</a></p><hr><h2 id="一口气口述模板-约-2-3-分钟压缩版" tabindex="-1">一口气口述模板（约 2～3 分钟压缩版） <a class="header-anchor" href="#一口气口述模板-约-2-3-分钟压缩版" aria-label="Permalink to “一口气口述模板（约 2～3 分钟压缩版）”">​</a></h2><blockquote><p>Redis 是内存键值库，我们主要做缓存和分布式锁。快是因为内存、高效结构和 I/O 多路复用；命令在主线程串行，所以单命令原子，但慢命令会堵全库。Redis 6 的多线程主要帮网络读写，命令执行仍偏单线程。<br> 类型里排行榜用 ZSet。缓存先 Redis 后 MySQL，防穿透用空值和布隆，防击穿用互斥或逻辑过期，过期加随机防雪崩。<br> 分布式锁用 <code>SET key uuid NX PX</code>：NX 互斥，PX 防死锁，uuid 防误删，释放用 Lua 原子校验删除。生产用 Redisson，看门狗负责续期。<br> 和 MySQL 一致一般是先更新库再删缓存；要更稳就 Binlog + MQ 异步删缓存。Redis Pub/Sub 不当可靠 MQ，核心异步还是专业消息中间件，Stream 只适合轻量场景。</p></blockquote><hr><h2 id="自测清单" tabindex="-1">自测清单 <a class="header-anchor" href="#自测清单" aria-label="Permalink to “自测清单”">​</a></h2><p>按链脱稿时，每一环能否用 <strong>一两句话</strong> 答完，并主动引出下一环：</p><ul><li>[ ] 为什么快 → 自然说到单线程</li><li>[ ] 单线程 → 自然说到 Redis 6 边界</li><li>[ ] 数据结构 → 主动举 ZSet 排行榜</li><li>[ ] 缓存 → 自己区分穿透 / 击穿</li><li>[ ] 锁 → NX、PX、唯一 value、Lua、Redisson、看门狗一条线</li><li>[ ] 一致性 → MySQL 怎么写、MQ 在一致性里干什么、和「Redis 当 MQ」有何不同</li></ul><p>卡哪一环，回上面链接的专题页补，再回到本链重练。</p><p>返回：<a href="./">Redis 总览</a></p>`,101)])])}const u=e(r,[["render",i]]);export{b as __pageData,u as default};
